/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.fn_fileSize
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.fn_fileSize = async function (idx) {
    /* sdd-asis-lifecycle:begin fn_fileSize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const yn = $c.util.getComponent('ipt_apiYn').getValue();
    const fSize = scwin.fileSizeChk($c.util.getComponent("attachUploadFile" + (idx)).files[0].size);
    if (fSize > 0) {
        if (yn === 'Y') {
            await $c.win.alert('첨부파일의 용량은 개당 100MB를 넘을수 없습니다.');
        } else {
            await $c.win.alert('첨부파일의 용량은 개당 30MB를 넘을수 없습니다.');
        }
        $c.util.getComponent("attachUploadFile" + (idx)).setValue("");
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


function urlInfo() {
    /* sdd-asis-lifecycle:begin fn_urlInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
    /* sdd-asis-lifecycle:end */
}

