/**
 * @method
 * @name scwin.calBytes
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.calBytes = function (str) {
    /* sdd-asis-lifecycle:begin fn_calBytes — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validation = async function () {
    /* sdd-asis-lifecycle:begin fn_validation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let boxCnt = 0;
    $("input[name=realInvstgMajContnCd]:checked").each(function(index, item) {
            boxCnt++;
    });
    if (($c.util.getComponent('ipt_title').getValue() == null ? '' : String($c.util.getComponent('ipt_title').getValue())) === '' || $c.util.getComponent('ipt_title').getValue() == null) {
        await $c.win.alert("제목을 작성하세요.");
        return false;
    }
    if (boxCnt == 0) {
        await $c.win.alert("주요내용을 선택해 주세요.");
        return false;
    }
    if (($c.util.getComponent('slc_realInvstgStepCd').getValue() == null ? '' : String($c.util.getComponent('slc_realInvstgStepCd').getValue())) === '') {
        await $c.win.alert("진행단계를 선택하세요.");
        return false;
    }
    if (($c.util.getComponent('txa_contn').getValue() == null ? '' : String($c.util.getComponent('txa_contn').getValue())) === '' || $c.util.getComponent('txa_contn').getValue() == null) {
        await $c.win.alert("비고를 작성하세요.");
        return false;
    }
    if (scwin.calBytes($c.util.getComponent('txa_contn').getValue()) > 4000) {
        await $c.win.alert("비고는 한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fileValidation = async function () {
    /* sdd-asis-lifecycle:begin fn_fileValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (let i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fileTypeChk(file.eq(i).attr("value"));
            fSize += scwin.fileSizeChk($c.util.getComponent("attachUploadFile" + (i + 1)).files[0].size);
        }
    }
    if (fNmLength > 0) {
        await $c.win.alert('파일명 길이가 80byte 초과된 파일이 ' + fNmLength + '개 있습니다.');
        return false;
    }
    if (fType > 0) {
        await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + fType + '개 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
        return false;
    }
    if (fSize > 0) {
        await $c.win.alert('첨부파일의 용량은 개당 100MB를 넘을수 없습니다.');
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileTypeChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.fileTypeChk = function (val) {
    /* sdd-asis-lifecycle:begin fn_fileTypeChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isFileType = new Array("DRT", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt");
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt == 0) {
        returnVal = 1;
    }
    return returnVal;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileSizeChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param fileSize
 * @returns
 * @hidden N
*/
scwin.fileSizeChk = function (fileSize) {
    /* sdd-asis-lifecycle:begin fn_fileSizeChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let mSize = 100;
    if ($c.util.getComponent('ipt_apiYn').getValue() === "N") {
        mSize = 30;
    }
    if (fileSize > (1024 * 1024 * mSize)) {
        return 1;
    }
    return 0;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.validation()) {
        return false;
    }
    if (!await scwin.fileValidation()) {
        return false;
    }
    scwin.showSpinner();
    if (!await $c.win.confirm('저장하시겠습니까? 저장후에는 수정이 불가능 합니다')) {
        scwin.hideSpinner();
        return;
    }
    if (await scwin.getRealInvstgProcsNo()) {
        $.each($('[type=file]'), function(i, item) {
                const f = $(item)[0].files[0];
                if (f == null || f === '') {
                    let idNum = $(item)[0].id;
                    idNum = idNum.replace('attachUploadFile', '');
                    $('#fileDiv' + idNum).remove();
                }
        });
        if ($c.util.getComponent('ipt_apiYn').getValue() === "Y" && $('[type=file]').length != 0) {
            await scwin.apiFileUpload();
        } else {
            await scwin.formSubmit();
        }
    }
    /* sdd-asis-lifecycle:end */
};


